function BarcodeLivePreview({ settings }) {
  const layout = normalizeBarcodeSettings(settings);
  const width = Math.min(300, Math.max(145, layout.labelWidth * 4));
  return <section className="barcode-live-preview" aria-label="Barcode sticker live preview"><div className="barcode-live-preview-heading"><strong>Live preview</strong><small>Single product sample</small></div><div className="barcode-live-preview-stage"><article className="barcode-live-preview-label" style={{ width, aspectRatio: `${layout.labelWidth} / ${layout.labelHeight}` }}>{layout.barcode_show_name === '1' && <strong>{BARCODE_PREVIEW_PRODUCT.name}</strong>}<span className="barcode-live-preview-bars" aria-hidden="true" dangerouslySetInnerHTML={{ __html: renderBarcodeSvg(BARCODE_PREVIEW_PRODUCT.barcode) }} />{layout.barcode_show_value === '1' && <code>{BARCODE_PREVIEW_PRODUCT.barcode}</code>}</article></div><small>{layout.labelWidth} × {layout.labelHeight} mm sticker</small></section>;
}

const SECTIONS = [
  ['account', 'Account', 'Profile and sign-in password', UserRound], ['shop', 'Business', 'Business identity', Store], ['timezone', 'Time zone', 'Business dates and operating hours', Globe], ['receipt', 'Receipt', 'Content and layout', ReceiptText], ['barcode', 'Barcode', 'Label paper and content', Barcode], ['printer', 'Printer', 'Device connection and paper', Printer],
  ['payments', 'Payment methods', 'Accepted payment methods', CreditCard], ['prices', 'Price types', 'Selling price rules', Tags], ['security', 'Security', 'Protected actions', ShieldCheck],
  ['data', 'Data tools', 'Backup and restore', Database], ['language', 'Language', 'Display language', Languages], ['about', 'About', 'Application information', Info],
];
function fieldErrorsFrom(error) { return Object.fromEntries(Object.entries(error?.payload?.errors || {}).map(([field, messages]) => [field, Array.isArray(messages) ? messages[0] : String(messages)])); }
function PageHeader({ title, copy, onBack, actions, backLabel = 'Back to settings' }) { return <PageAppBar as="section" className="settings-reference-header">{onBack && <IconButton variant="ghost" type="button" className="icon-button" aria-label={backLabel} onClick={onBack}><ArrowLeft size={21} /></IconButton>}<div><span className="page-kicker">Settings</span><h1>{title}</h1><p>{copy}</p></div>{actions}<AppBarMenu /></PageAppBar>; }

function PriceEditor({ mode, originalName, rows, onNavigate, onChanged }) {
  const source = rows.find((row) => row.name.toLowerCase() === String(originalName || '').toLowerCase());
  const [form, setForm] = useState(() => source || { name: '', pricing_mode: 'manual', markup_percent: 0, rounding: 1, minimum_profit: 0, apply_to_existing: false, productCount: 0 });
  const [errors, setErrors] = useState({}); const [saving, setSaving] = useState(false);
  useEffect(() => { if (mode === 'edit' && source) setForm(source); }, [mode, source]);
  async function submit(event) { event.preventDefault(); setErrors({}); if (!form.name.trim()) return setErrors({ name: 'Price type name is required.' }); try { setSaving(true); const path = mode === 'new' ? '/price-types' : `/price-types/${encodeURIComponent(originalName)}`; const payload = await apiRequest(path, { method: mode === 'new' ? 'POST' : 'PUT', body: JSON.stringify({ name: form.name.trim(), pricing_mode: form.pricing_mode, markup_percent: Number(form.markup_percent || 0), rounding: Number(form.rounding || 1), minimum_profit: Number(form.minimum_profit || 0), apply_to_existing: Boolean(form.apply_to_existing) }) }); if (mode === 'new') setForm({ name: '', pricing_mode: 'manual', markup_percent: 0, rounding: 1, minimum_profit: 0, apply_to_existing: false, productCount: 0 }); onChanged(payload); onNavigate('/settings/prices', { replace: true }); } catch (error) { const fields = fieldErrorsFrom(error); setErrors(Object.keys(fields).length ? fields : { general: error.message }); } finally { setSaving(false); } }
  if (mode === 'edit' && !source) return <div className="endless-first-error"><p>Price type not found.</p><Button variant="plain" type="button" onClick={() => onNavigate('/settings/prices')}>Back</Button></div>;
  return <main className="settings-page settings-form-page">
    <PageHeader title={mode === 'new' ? 'New price type' : 'Edit price type'} onBack={() => onNavigate('/settings/prices')} />
    <form className="settings-mobile-form" onSubmit={submit} noValidate>
      <SettingsSection title="Name" description="A name to identify this price type.">
        <SettingField label="Price type name" error={errors.name}><Input autoFocus value={form.name} onChange={event => setForm({ ...form, name: event.target.value })} /></SettingField>
      </SettingsSection>
      <SettingsSection title="Pricing mode" description="Choose how prices are calculated for each product.">
        <SettingsChoices label="Pricing mode" className="settings-pricing-mode" value={form.pricing_mode} onChange={pricing_mode => setForm({ ...form, pricing_mode })} options={[
          { value: 'manual', label: 'Manual', description: 'Set prices manually for each product.' },
          { value: 'automatic', label: 'Automatic', description: 'Calculate prices from buying cost, markup and rounding.' },
        ]} />
      </SettingsSection>
      <SettingsSection title="Automatic pricing settings" description="Set how to calculate the selling price from cost.">
        <div className="settings-pricing-fields">
          <SettingField label="Markup %"><Input type="number" min="0" step=".01" disabled={form.pricing_mode !== 'automatic'} value={form.markup_percent} onChange={event => setForm({ ...form, markup_percent: event.target.value })} /></SettingField>
          <SettingField label="Round up to"><Select disabled={form.pricing_mode !== 'automatic'} value={form.rounding} onChange={event => setForm({ ...form, rounding: event.target.value })}>{[1,10,50,100,500,1000].map(value => <option value={value} key={value}>{value} Ks</option>)}</Select></SettingField>
          <SettingField label="Minimum profit"><Input type="number" min="0" disabled={form.pricing_mode !== 'automatic'} value={form.minimum_profit} onChange={event => setForm({ ...form, minimum_profit: event.target.value })} /></SettingField>
        </div>
        {form.pricing_mode === 'automatic' && <div className="settings-info-note settings-price-example"><strong>Example calculation</strong><small>For a product with cost 1,000</small><dl>
          <div><dt>Markup</dt><dd>{form.markup_percent}%</dd></div><div><dt>Minimum profit</dt><dd>{Number(form.minimum_profit || 0).toLocaleString()}</dd></div><div><dt>Round up to</dt><dd>{Number(form.rounding || 1).toLocaleString()}</dd></div><div><dt>Calculated price</dt><dd>{automaticSellingPrice(1000, form).toLocaleString()}</dd></div>
        </dl></div>}
      </SettingsSection>
      {mode === 'edit' && <SettingsSection title="Usage"><p className="settings-usage">Used by {form.productCount || 0} active products.</p></SettingsSection>}
      {mode === 'edit' && form.pricing_mode === 'automatic' && <SettingsSection title="Apply to existing products">
        <label className="settings-check"><Checkbox checked={form.apply_to_existing} onChange={event => setForm({ ...form, apply_to_existing: event.target.checked })} /><span><strong>Apply to existing products</strong><small>Replaces current prices calculated from latest buying cost.</small></span></label>
      </SettingsSection>}
      {errors.general && <div className="mobile-notice mobile-notice--error" role="alert">{errors.general}</div>}
      <div className="mobile-form-actions"><Button variant="secondary" onClick={() => onNavigate('/settings/prices')}>Cancel</Button><Button variant="primary" type="submit" busy={saving}>{saving ? 'Saving?' : 'Save price type'}</Button></div>
    </form>
  </main>;

}

export function SettingsScreen(props) { return <ModuleLocalizationBoundary messages={settingsMessages} patterns={REMAINING_PAGE_PATTERNS}>{props.pathname === '/settings/printer' ? <PrinterSettingsPage onNavigate={props.onNavigate} /> : <SettingsScreenContent {...props} />}</ModuleLocalizationBoundary>; }

function RestorePage({ settings, restricted, language, onNavigate, onRestored }) {
  const [file, setFile] = useState(null); const [confirmation, setConfirmation] = useState(''); const [pin, setPin] = useState(''); const [errors, setErrors] = useState({}); const [saving, setSaving] = useState(false);
  async function submit(event) { event.preventDefault(); const submittedForm = event.currentTarget; setErrors({}); if (!file) return setErrors({ backup: 'Choose a backup file.' }); if (confirmation !== 'RESTORE') return setErrors({ confirmation: 'Type RESTORE exactly.' }); const body = new FormData(); body.append('backup', file); body.append('confirmation', confirmation); if (pin) body.append('admin_pin', pin); try { setSaving(true); const result = await apiRequest('/data/restore-file', { method: 'POST', body, timeoutMs: 120000 }); setFile(null); setConfirmation(''); setPin(''); submittedForm?.reset(); await onRestored(result); onNavigate('/settings/data', { replace: true }); } catch (error) { const fields = fieldErrorsFrom(error); setErrors(Object.keys(fields).length ? fields : { general: error.message }); } finally { setSaving(false); } }
  if (restricted) return <main className="settings-page settings-form-page"><PageHeader title={language === 'my' ? 'ဒေတာပြန်သွင်းရန်' : 'Restore backup'} copy={language === 'my' ? 'ဤလုပ်ဆောင်ချက်အတွက် ငွေပေးချေထားသောအစီအစဉ် လိုအပ်သည်။' : 'This feature requires a paid plan.'} onBack={() => onNavigate('/settings/data')} /><div className="settings-danger-note" role="alert"><ShieldAlert size={19} /><span><strong>{language === 'my' ? 'အခမဲ့စမ်းသုံးကာလတွင် မရနိုင်ပါ' : 'Unavailable during the free trial'}</strong><small>{language === 'my' ? 'ဒေတာအရန်ကူးယူခြင်းနှင့် ပြန်လည်ထည့်သွင်းခြင်းအတွက် ငွေပေးချေထားသောအစီအစဉ်ကို ရွေးချယ်ပါ။' : 'Choose a paid plan to download or restore business backups.'}</small></span></div><Button variant="primary" className="mobile-primary" type="button" onClick={() => onNavigate('/billing')}>{language === 'my' ? 'အစီအစဉ်များကြည့်ရန်' : 'View Billing'}</Button></main>;
  return <main className="settings-page settings-form-page"><PageHeader title="Restore backup" copy="This replaces operational data for the current business." onBack={() => onNavigate('/settings/data')} /><form className="settings-mobile-form" onSubmit={submit} noValidate><section className="mobile-form-section"><div className="settings-danger-note"><ShieldAlert size={19} /><span><strong>Existing records will be replaced</strong><small>Products, sales, purchases, customers, suppliers, expenses and settings are restored from the chosen file.</small></span></div><label className={`settings-file-picker${errors.backup ? ' has-error' : ''}`}><Upload size={22} /><span><strong>{file?.name || 'Choose .mkpos-backup file'}</strong><small>Maximum file size 25 MB</small></span><Input className="visually-hidden" type="file" accept=".mkpos-backup,application/gzip" onChange={(event) => setFile(event.target.files?.[0] || null)} /></label>{errors.backup && <p className="mobile-field-error" role="alert">{errors.backup}</p>}<SettingField label="Confirmation" error={errors.confirmation} hint="Type RESTORE in uppercase."><Input value={confirmation} onChange={(event) => setConfirmation(event.target.value)} placeholder="RESTORE" /></SettingField>{settings.admin_pin_set === '1' && <SettingField label="Admin PIN" error={errors.admin_pin}><SettingsPassword inputMode="numeric" value={pin} onChange={(event) => setPin(event.target.value)} /></SettingField>}{errors.general && <div className="mobile-notice mobile-notice--error" role="alert">{errors.general}</div>}</section><div className="mobile-form-actions"><Button variant="secondary" className="mobile-secondary" type="button" onClick={() => onNavigate('/settings/data')}>Cancel</Button><Button variant="danger" className="mobile-danger" type="submit" disabled={saving}>{saving ? 'Restoring…' : 'Restore backup'}</Button></div></form></main>;
}

function ResetDataPage({ settings, onNavigate, onReset }) {
  const [confirmation, setConfirmation] = useState('');
  const [pin, setPin] = useState('');
  const [errors, setErrors] = useState({});
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [saving, setSaving] = useState(false);

  function submit(event) {
    event.preventDefault();
    setErrors({});
    if (confirmation !== 'RESET') {
      setErrors({ confirmation: 'Type RESET exactly.' });
      return;
    }
    setConfirmOpen(true);
  }

  async function resetBusinessData() {
    setErrors({});
    try {
      setSaving(true);
      const result = await apiRequest('/data/reset', {
        method: 'POST',
        body: JSON.stringify({ confirmation, admin_pin: pin }),
        timeoutMs: 120000,
      });
      setConfirmation('');
      setPin('');
      setConfirmOpen(false);
      await onReset(result);
      onNavigate('/settings/data', { replace: true });
    } catch (error) {
      const fields = fieldErrorsFrom(error);
      setErrors(Object.keys(fields).length ? fields : { general: error.message });
      setConfirmOpen(false);
    } finally {
      setSaving(false);
    }
  }

  return <><main className="settings-page settings-form-page"><PageHeader title="Start with a fresh business" copy="Clear operational data while preserving your account and subscription." onBack={() => onNavigate('/settings/data')} /><form className="settings-mobile-form" onSubmit={submit} noValidate><section className="mobile-form-section"><div className="mobile-section-heading"><span>01</span><div><h3>Review what will change</h3><p>Review the records below before continuing.</p></div></div><div className="settings-danger-note" role="note"><ShieldAlert size={19} /><span><strong>Operational data will be permanently cleared</strong><small>This action cannot be undone from this device.</small></span></div><div className="settings-reset-scope"><h3>What will be removed</h3><ul><li>Products, prices and stock history</li><li>Customers, suppliers and payments</li><li>Sales, purchases and expenses</li><li>Shop settings</li></ul><h3>What will be preserved</h3><ul><li>Business account, users and passwords</li><li>Access roles</li><li>Subscription and billing records</li></ul></div><div className="settings-info-note"><strong>Safety backup</strong><p>A server-side safety backup is created before records are cleared.</p></div></section><section className="mobile-form-section"><div className="mobile-section-heading"><span>02</span><div><h3>Confirm the reset</h3><p>Type the required word exactly before continuing.</p></div></div><FieldShell className="mobile-field"><label htmlFor="settings-reset-confirmation">Type RESET to confirm</label><Input id="settings-reset-confirmation" autoComplete="off" value={confirmation} onChange={(event) => setConfirmation(event.target.value)} placeholder="RESET" aria-invalid={Boolean(errors.confirmation)} aria-describedby={errors.confirmation ? 'settings-reset-confirmation-error' : 'settings-reset-confirmation-hint'} /><small id="settings-reset-confirmation-hint">Use uppercase letters.</small>{errors.confirmation && <small id="settings-reset-confirmation-error" className="mobile-field-error" role="alert">{errors.confirmation}</small>}</FieldShell>{settings.admin_pin_set === '1' && <FieldShell className="mobile-field"><label htmlFor="settings-reset-pin">Admin PIN</label><Input id="settings-reset-pin" type="password" inputMode="numeric" autoComplete="current-password" value={pin} onChange={(event) => setPin(event.target.value)} aria-invalid={Boolean(errors.admin_pin)} aria-describedby={errors.admin_pin ? 'settings-reset-pin-error' : undefined} />{errors.admin_pin && <small id="settings-reset-pin-error" className="mobile-field-error" role="alert">{errors.admin_pin}</small>}</FieldShell>}{errors.general && <div className="mobile-notice mobile-notice--error" role="alert">{errors.general}</div>}</section><div className="mobile-form-actions"><Button variant="secondary" className="mobile-secondary" type="button" disabled={saving} onClick={() => onNavigate('/settings/data')}>Cancel</Button><Button variant="danger" className="mobile-danger" type="submit" disabled={saving || confirmation !== 'RESET'}><Trash2 size={17} />Clear business data</Button></div></form></main><MobileDeleteSheet open={confirmOpen} title="Start with a fresh business?" description="This cannot be undone from the app." itemTitle="Clear all operational data" itemDescription="A server-side safety backup is created first. Your account, users, roles, and subscription remain available." cancelLabel="Keep my data" confirmLabel="Clear business data" busyLabel="Clearing…" busy={saving} onClose={() => setConfirmOpen(false)} onConfirm={resetBusinessData} /></>;
}

function SettingsScreenContent({ pathname = '/settings', onNavigate = () => {}, onAssistantBack }) {
  const platformContacts = usePlatformContacts();
  const { language, setLanguage } = useLocale();
  const page = settingsPageFromPath(pathname);
  const [settings, setSettings] = useState(DEFAULT_SETTINGS);
  const [deletionOpen, setDeletionOpen] = useState(false);
  const logoInputRef = useRef(null);
  const [account, setAccount] = useState({ name: '', email: '', role: '', current_password: '', password: '', password_confirmation: '' });
  const [priceRows, setPriceRows] = useState([]); const [dataStatus, setDataStatus] = useState(null); const [subscription, setSubscription] = useState(null); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [notice, setNotice] = useState(null); const [errors, setErrors] = useState({}); const [actionPrice, setActionPrice] = useState(null); const [deletePrice, setDeletePrice] = useState(null); const [preview, setPreview] = useState(null); const [previewing, setPreviewing] = useState(false);
  const loadAll = useCallback(async (signal) => { const options = signal ? { signal } : undefined; const session = await apiRequest('/auth/me', options); const owner = session.user?.role === 'owner'; const [settingRows, prices, status] = await Promise.all([apiRequest('/settings', options), owner ? apiRequest('/price-types', options) : Promise.resolve(null), owner ? apiRequest('/data/status', options) : Promise.resolve(null)]); setSettings({ ...DEFAULT_SETTINGS, ...settingRows, admin_pin: '' }); setAccount((current) => ({ ...current, name: session.user?.name || '', email: session.user?.email || '', role: session.user?.role || '' })); setSubscription(session.subscription || null); if (owner) { setPriceRows(priceTypeRows(prices)); setDataStatus(status); } if (isAndroidPrinter()) { const profile = await NativePrinter.getConfig(); setSettings(current => ({ ...current, receipt_paper_size: profile.paper })); } }, []);
  useEffect(() => { const controller = new AbortController(); setLoading(true); loadAll(controller.signal).catch((error) => !controller.signal.aborted && setNotice({ type: 'error', text: error.message })).finally(() => !controller.signal.aborted && setLoading(false)); return () => controller.abort(); }, [loadAll]);
  usePageRefresh(loadAll);
  useEffect(() => { if (page.section !== 'receipt' || loading) return undefined; const timer = window.setTimeout(() => { setPreviewing(true); apiRequest('/settings/receipt-preview', { method: 'POST', body: JSON.stringify(settingsPayload(settings)) }).then(setPreview).catch((error) => setNotice({ type: 'error', text: error.message })).finally(() => setPreviewing(false)); }, 250); return () => window.clearTimeout(timer); }, [loading, page.section, settings]);
  const methods = useMemo(() => paymentMethodRows(settings.payment_methods), [settings.payment_methods]);
  const visibleSections = settingsSectionsForRole(SECTIONS, account.role);
  const staffCanOpenSection = visibleSections.some(([id]) => id === page.section);
  const trialRestricted = subscription?.is_valid && subscription?.access_type === 'trial';
  async function saveSettings(event, patch = {}) { event?.preventDefault?.(); setErrors({}); setNotice(null); try { setSaving(true); const saved = await apiRequest('/settings', { method: 'PUT', body: JSON.stringify(sharedMobileSettings(settingsPayload(settings, patch))) }); setSettings({ ...DEFAULT_SETTINGS, ...saved, admin_pin: '' }); setLanguage(saved.language); setNotice({ type: 'success', text: 'Settings saved.' }); onNavigate('/settings', { replace: true }); } catch (error) { const fields = fieldErrorsFrom(error); setErrors(Object.keys(fields).length ? fields : { general: error.message }); } finally { setSaving(false); } }
  async function saveAccount(event) { event.preventDefault(); setErrors({}); try { setSaving(true); const session = await apiRequest('/auth/profile', { method: 'PUT', body: JSON.stringify({ name: account.name.trim(), email: account.email.trim(), current_password: account.current_password, password: account.password || null, password_confirmation: account.password_confirmation || null }) }); setAccount(current => ({ ...current, name: session.user.name, email: session.user.email, current_password: '', password: '', password_confirmation: '' })); window.dispatchEvent(new CustomEvent('mkpos:session-updated', { detail: session })); setNotice({ type: 'success', text: 'Account updated.' }); onNavigate('/settings', { replace: true }); } catch (error) { const fields = fieldErrorsFrom(error); setErrors(Object.keys(fields).length ? fields : { general: error.message }); } finally { setSaving(false); } }
  async function uploadShopLogo(event) { const file = event.target.files?.[0]; event.target.value = ''; if (!file) return; setErrors({}); setNotice(null); if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type)) { setErrors({ logo: 'Choose a JPG, PNG, or WebP image.' }); return; } if (file.size > 512 * 1024) { setErrors({ logo: 'Shop logo must be 512 KB or smaller.' }); return; } const body = new FormData(); body.append('logo', file); try { setSaving(true); const saved = await apiRequest('/settings/logo', { method: 'POST', body }); setSettings({ ...DEFAULT_SETTINGS, ...saved, admin_pin: '' }); window.dispatchEvent(new CustomEvent('mkpos:shop-logo-updated', { detail: saved.receipt_logo_data_url || '' })); setNotice({ type: 'success', text: 'Shop logo updated.' }); } catch (error) { const fields = fieldErrorsFrom(error); setErrors(Object.keys(fields).length ? fields : { logo: error.message }); } finally { setSaving(false); } }
  async function removeShopLogo() { setErrors({}); setNotice(null); try { setSaving(true); const saved = await apiRequest('/settings/logo', { method: 'DELETE' }); setSettings({ ...DEFAULT_SETTINGS, ...saved, admin_pin: '' }); window.dispatchEvent(new CustomEvent('mkpos:shop-logo-updated', { detail: '' })); setNotice({ type: 'success', text: 'Shop logo removed.' }); } catch (error) { setErrors({ logo: error.message }); } finally { setSaving(false); } }
  async function deletePriceType() { try { setSaving(true); const payload = await apiRequest(`/price-types/${encodeURIComponent(deletePrice.name)}`, { method: 'DELETE' }); setPriceRows(priceTypeRows(payload)); setDeletePrice(null); setNotice({ type: 'success', text: 'Price type deleted.' }); } catch (error) { setNotice({ type: 'error', text: error.message }); } finally { setSaving(false); } }
  async function testPrint() { try { setSaving(true); const result = await apiRequest('/settings/test-print', { method: 'POST', body: JSON.stringify(settingsPayload(settings)) }); if (!await printHtmlDocument({ title: 'Test receipt', html: result.html || result.receipt_html, text: result.text || result.receipt_text, ...receiptOptions(result, settings) })) setNotice({ type: 'error', text: 'Allow pop-ups to print.' }); } catch (error) { setNotice({ type: 'error', text: error.message }); } finally { setSaving(false); } }
  async function exportBackup() { try { setSaving(true); const response = await apiDownload('/data/export', { accept: 'application/gzip' }); const blob = await response.blob(); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = response.headers.get('Content-Disposition')?.match(/filename="?([^";]+)/i)?.[1] || `mkpos-backup-${new Date().toISOString().slice(0, 10)}.mkpos-backup`; document.body.appendChild(anchor); anchor.click(); anchor.remove(); URL.revokeObjectURL(url); setNotice({ type: 'success', text: 'Business backup downloaded.' }); } catch (error) { setNotice({ type: 'error', text: error.message }); } finally { setSaving(false); } }

  if (loading) return <main className="settings-page"><p className="mobile-inline-loading"><RefreshCw className="spin" size={18} />Loading settings…</p></main>;
  if (account.role !== 'owner' && page.section !== 'overview' && !staffCanOpenSection) return <main className="settings-page settings-form-page"><PageHeader title="Owner-only settings" copy="This section changes protected business configuration." onBack={() => onNavigate('/settings')} /><div className="settings-danger-note" role="alert"><ShieldAlert size={19} /><span><strong>Owner access required</strong><small>Staff can use Profile, Receipt, Printer, Barcode, and About settings.</small></span></div></main>;
  if (page.section === 'price-new' || page.section === 'price-edit') return <PriceEditor mode={page.section === 'price-new' ? 'new' : 'edit'} originalName={page.value} rows={priceRows} onNavigate={onNavigate} onChanged={(payload) => setPriceRows(priceTypeRows(payload))} />;
  if (page.section === 'restore') return <RestorePage settings={settings} restricted={trialRestricted} language={language} onNavigate={onNavigate} onRestored={(result) => { setNotice({ type: 'success', text: `${Number(result.records_restored || 0).toLocaleString()} records restored.` }); return loadAll(); }} />;
  if (page.section === 'reset') return <ResetDataPage settings={settings} onNavigate={onNavigate} onReset={(result) => { setNotice({ type: 'success', text: `${Number(result.records_cleared || 0).toLocaleString()} business records cleared. Your account and subscription were preserved.` }); return loadAll(); }} />;
  if (page.section === 'overview') return <main className="settings-page settings-overview"><PageHeader title="Settings" onBack={onAssistantBack} backLabel="Back to PwarMyar AI" /><MobileNotice notice={notice} onClose={() => setNotice(null)} />{[['Identity & Business', ['account', 'shop', 'timezone']], ['Output & Device', ['receipt', 'barcode', 'printer']], ['Administration', ['payments', 'prices', 'security', 'data', 'language']], ['Help', ['about']]].map(([heading, ids]) => { const sections = visibleSections.filter(([id]) => ids.includes(id)); return sections.length ? <section className="settings-navigation-group" key={heading}><h2>{heading}</h2><div className="settings-section-grid">{sections.map(([id, title, copy, Icon]) => <Button variant="plain" type="button" aria-label={`Open ${title}`} key={id} onClick={() => onNavigate(`/settings/${id}`)}><span><Icon size={20} /></span><span><strong>{title}</strong><small>{copy}</small></span><ChevronRight className="settings-section-arrow" size={18} aria-hidden="true" /></Button>)}</div></section> : null; })}</main>;
  const sectionInfo = SECTIONS.find(([id]) => id === page.section);
  const back = () => onNavigate('/settings');
  if (page.section === 'barcode') {
    const layout = normalizeBarcodeSettings(settings);
    const custom = String(settings.barcode_label_format).startsWith('custom_');
    const customSheet = settings.barcode_label_format === 'custom_sheet';
    const patchBarcode = (patch) => setSettings({ ...settings, ...patch });
    return <main className="settings-page settings-form-page"><PageHeader title="Barcode" copy="Sticker paper and label content" onBack={back} /><MobileNotice notice={notice} onClose={() => setNotice(null)} /><form className="settings-mobile-form" onSubmit={saveSettings} noValidate><SettingsSection title="Label format" description="Choose the physical sticker stock loaded in the printer."><SettingField label="Sticker paper format"><Select value={settings.barcode_label_format} onChange={(event) => patchBarcode({ barcode_label_format: event.target.value })}>{Object.entries(BARCODE_LABEL_FORMATS).map(([value, format]) => <option value={value} key={value}>{format.label}</option>)}</Select></SettingField>{custom && <div className="mobile-two-fields">{customSheet && <><SettingField label="Paper width (mm)"><Input type="number" min="20" max="400" step=".1" value={settings.barcode_page_width_mm} onChange={(event) => patchBarcode({ barcode_page_width_mm: event.target.value })} /></SettingField><SettingField label="Paper height (mm)"><Input type="number" min="20" max="600" step=".1" value={settings.barcode_page_height_mm} onChange={(event) => patchBarcode({ barcode_page_height_mm: event.target.value })} /></SettingField></>}<SettingField label="Sticker width (mm)"><Input type="number" min="15" max="200" step=".1" value={settings.barcode_label_width_mm} onChange={(event) => patchBarcode({ barcode_label_width_mm: event.target.value, ...(!customSheet ? { barcode_page_width_mm: event.target.value } : {}) })} /></SettingField><SettingField label="Sticker height (mm)"><Input type="number" min="18" max="120" step=".1" value={settings.barcode_label_height_mm} onChange={(event) => patchBarcode({ barcode_label_height_mm: event.target.value, ...(!customSheet ? { barcode_page_height_mm: event.target.value } : {}) })} /></SettingField>{customSheet && <><SettingField label="Side margin (mm)"><Input type="number" min="0" max="30" step=".1" value={settings.barcode_margin_x_mm} onChange={(event) => patchBarcode({ barcode_margin_x_mm: event.target.value })} /></SettingField><SettingField label="Top margin (mm)"><Input type="number" min="0" max="30" step=".1" value={settings.barcode_margin_y_mm} onChange={(event) => patchBarcode({ barcode_margin_y_mm: event.target.value })} /></SettingField><SettingField label="Horizontal gap (mm)"><Input type="number" min="0" max="20" step=".1" value={settings.barcode_gap_x_mm} onChange={(event) => patchBarcode({ barcode_gap_x_mm: event.target.value })} /></SettingField><SettingField label="Vertical gap (mm)"><Input type="number" min="0" max="20" step=".1" value={settings.barcode_gap_y_mm} onChange={(event) => patchBarcode({ barcode_gap_y_mm: event.target.value })} /></SettingField></>}</div>}<div className="settings-format-summary"><strong>{layout.labelWidth} × {layout.labelHeight} mm sticker</strong><small>{layout.mode === 'roll' ? 'One sticker per printed page' : `${layout.columns} columns × ${layout.rows} rows · ${layout.labelsPerPage} stickers per page`}</small></div></SettingsSection><SettingsSection title="Label content">{[['barcode_show_name', 'Show product name'], ['barcode_show_value', 'Show barcode number']].map(([key, label]) => <SettingsToggle key={key} label={label} checked={settings[key] === '1'} onChange={event => patchBarcode({ [key]: event.target.checked ? '1' : '0' })} />)}</SettingsSection><SettingsSection title="Preview"><BarcodeLivePreview settings={settings} />{errors.general && <div className="mobile-notice mobile-notice--error" role="alert">{errors.general}</div>}</SettingsSection><div className="mobile-form-actions"><Button variant="secondary" className="mobile-secondary" type="button" onClick={back}>Cancel</Button><Button variant="primary" className="mobile-primary" type="submit" disabled={saving}>{saving ? 'Saving…' : 'Save barcode'}</Button></div></form></main>;
  }
  return <><main className={`settings-page settings-form-page${page.section === 'prices' ? ' has-create-fab' : ''}`}><PageHeader title={sectionInfo?.[1] || 'Settings'} copy={sectionInfo?.[2] || ''} onBack={back} />{page.section === 'prices' && <FloatingActionButton label="New price type" onClick={() => onNavigate('/settings/prices/new')}><Plus size={24} aria-hidden="true" /></FloatingActionButton>}<MobileNotice notice={notice} onClose={() => setNotice(null)} />{page.section === 'timezone' && <BusinessTimezoneSettings onCancel={back} onSaved={() => { setNotice({ type: 'success', text: 'Business time zone saved.' }); onNavigate('/settings', { replace: true }); }} />}{page.section === 'account' && <form className="settings-mobile-form" onSubmit={saveAccount} noValidate><section className="mobile-form-section"><h3>Profile</h3><div className="settings-account-card"><span>{account.name.charAt(0).toUpperCase() || 'O'}</span><div><strong>{account.name || 'Business owner'}</strong><small>{account.email}</small></div><b>{account.role}</b></div><SettingField label="Owner name" error={errors.name}><Input required value={account.name} onChange={(event) => setAccount({ ...account, name: event.target.value })} /></SettingField><SettingField label="Email address" error={errors.email}><Input type="email" required value={account.email} onChange={(event) => setAccount({ ...account, email: event.target.value })} /></SettingField></section><section className="mobile-form-section"><div className="mobile-section-heading"><span>02</span><div><h3>Change password</h3><p>Current password is required for every profile change.</p></div></div><SettingField label="Current password" error={errors.current_password}><SettingsPassword required value={account.current_password} onChange={(event) => setAccount({ ...account, current_password: event.target.value })} /></SettingField><div className="mobile-two-fields"><SettingField label="New password" error={errors.password}><SettingsPassword minLength="8" value={account.password} onChange={(event) => setAccount({ ...account, password: event.target.value })} /></SettingField><SettingField label="Confirm password"><SettingsPassword value={account.password_confirmation} onChange={(event) => setAccount({ ...account, password_confirmation: event.target.value })} /></SettingField></div>{errors.general && <div className="mobile-notice mobile-notice--error" role="alert">{errors.general}</div>}</section><div className="mobile-form-actions"><Button variant="secondary" className="mobile-secondary" type="button" onClick={back}>Cancel</Button><Button variant="primary" className="mobile-primary" type="submit" disabled={saving}>{saving ? 'Saving…' : 'Save account'}</Button></div></form>}
      {page.section === 'account' && <SettingsSection title={language === 'my' ? 'အကောင့်ဖျက်ရန်' : 'Account deletion'}><Button variant="danger-ghost" onClick={() => setDeletionOpen(true)}>{language === 'my' ? 'အကောင့်ဖျက်ရန် တောင်းဆိုမည်' : 'Request account deletion'}</Button><MobileSheet open={deletionOpen} title={language === 'my' ? 'အကောင့်ဖျက်ရန် တောင်းဆိုမည်' : 'Request account deletion'} onClose={() => setDeletionOpen(false)}><AccountDeletionRequest contacts={platformContacts} accountEmail={account.email} /><p><a href={accountDeletionUrl()} target="_blank" rel="noreferrer">{language === 'my' ? 'အများသုံး အကောင့်ဖျက်ရန် စာမျက်နှာ' : 'Public account-deletion page'}</a></p></MobileSheet></SettingsSection>}
      {page.section === 'shop' && <form className="settings-mobile-form" onSubmit={saveSettings} noValidate><section className="mobile-form-section"><div className="mobile-section-heading"><span>01</span><div><h3>Business identity</h3><p>Used in the workspace and printed receipts.</p></div></div><div className="settings-shop-logo"><span className={`settings-shop-logo-preview${settings.receipt_logo_data_url ? ' has-logo' : ''}`}>{settings.receipt_logo_data_url ? <img src={settings.receipt_logo_data_url} alt={`${settings.shop_name || 'Shop'} logo`} /> : <ImagePlus size={26} aria-hidden="true" />}</span><span className="settings-shop-logo-copy"><strong>Shop logo</strong><small>JPG, PNG, or WebP · maximum 512 KB</small></span><div className="settings-shop-logo-actions"><Button variant="secondary" className="mobile-secondary" type="button" disabled={saving} onClick={() => logoInputRef.current?.click()}><Upload size={16} />{settings.receipt_logo_data_url ? 'Replace' : 'Upload'}</Button>{settings.receipt_logo_data_url && <Button variant="danger" className="mobile-danger" type="button" disabled={saving} onClick={removeShopLogo}><Trash2 size={16} />Remove</Button>}</div><Input ref={logoInputRef} className="visually-hidden" type="file" accept="image/jpeg,image/png,image/webp" aria-label="Choose shop logo" onChange={uploadShopLogo} /></div>{errors.logo && <p className="mobile-field-error" role="alert">{errors.logo}</p>}<SettingField label="Shop name" error={errors.shop_name}><Input required value={settings.shop_name} onChange={(event) => setSettings({ ...settings, shop_name: event.target.value })} /></SettingField><SettingField label="Address"><Textarea rows="3" value={settings.shop_address} onChange={(event) => setSettings({ ...settings, shop_address: event.target.value })} /></SettingField><div className="mobile-two-fields"><SettingField label="Phone"><Input type="tel" value={settings.shop_phone} onChange={(event) => setSettings({ ...settings, shop_phone: event.target.value })} /></SettingField><SettingField label="Currency"><Input value={settings.currency} onChange={(event) => setSettings({ ...settings, currency: event.target.value })} /></SettingField></div>{errors.general && <div className="mobile-notice mobile-notice--error" role="alert">{errors.general}</div>}</section><div className="mobile-form-actions"><Button variant="secondary" className="mobile-secondary" type="button" onClick={back}>Cancel</Button><Button variant="primary" className="mobile-primary" type="submit" disabled={saving}>{saving ? 'Saving…' : 'Save shop'}</Button></div></form>}
      {page.section === 'receipt' && <form className="settings-mobile-form" onSubmit={saveSettings} noValidate><section className="mobile-form-section"><h3>Receipt layout</h3><p>Printer connection and device paper are configured separately.</p><Button variant="secondary" type="button" className="mobile-secondary" onClick={() => onNavigate('/settings/printer')}>Printer settings</Button>{!isAndroidPrinter() && <SettingsSegments label="Paper size" value={settings.receipt_paper_size} options={['50mm', '58mm', '80mm', '85mm', 'a5', 'a4'].map(value => ({ value, label: value.toUpperCase() }))} onChange={receipt_paper_size => setSettings({ ...settings, receipt_paper_size })} />}</section><section className="mobile-form-section"><div className="mobile-section-heading"><span>02</span><div><h3>Receipt content</h3><p>Title, footer and optional sale metadata.</p></div></div><SettingField label="Receipt title"><Input value={settings.shop_title} onChange={(event) => setSettings({ ...settings, shop_title: event.target.value })} /></SettingField><SettingField label="Footer"><Textarea rows="3" value={settings.receipt_footer} onChange={(event) => setSettings({ ...settings, receipt_footer: event.target.value })} /></SettingField>{[['receipt_show_customer','Show customer'],['receipt_show_payment_method','Show payment method'],['receipt_show_price_type','Show price type']].map(([key,label]) => <SettingsToggle key={key} label={label} checked={settings[key] === '1'} onChange={event => setSettings({ ...settings, [key]: event.target.checked ? '1' : '0' })} />)}</section><section className="mobile-form-section"><div className="mobile-section-heading"><span>03</span><div><h3>Layout</h3><p>Spacing, alignment and text sizes.</p></div></div><SettingsSegments label="Header alignment" value={settings.receipt_header_alignment} options={['left', 'center', 'right'].map(value => ({ value, label: value[0].toUpperCase() + value.slice(1) }))} onChange={receipt_header_alignment => setSettings({ ...settings, receipt_header_alignment })} /><div className="mobile-three-fields"><SettingField label="Left margin"><Input type="number" min="0" max="30" step=".5" value={settings.receipt_margin_left} onChange={(event) => setSettings({ ...settings, receipt_margin_left: event.target.value })} /></SettingField><SettingField label="Right margin"><Input type="number" min="0" max="30" step=".5" value={settings.receipt_margin_right} onChange={(event) => setSettings({ ...settings, receipt_margin_right: event.target.value })} /></SettingField><SettingField label="Line spacing"><Input type="number" min="1" max="2.2" step=".05" value={settings.receipt_line_height} onChange={(event) => setSettings({ ...settings, receipt_line_height: event.target.value })} /></SettingField></div><div className="mobile-two-fields"><SettingField label="Header size"><Input type="number" min="7" max="24" step=".5" value={settings.receipt_header_font_size} onChange={(event) => setSettings({ ...settings, receipt_header_font_size: event.target.value })} /></SettingField><SettingField label="Body size"><Input type="number" min="6" max="18" step=".1" value={settings.receipt_body_font_size} onChange={(event) => setSettings({ ...settings, receipt_body_font_size: event.target.value })} /></SettingField></div><ReceiptPreview preview={preview} settings={settings} preparing={previewing} /></section><div className="mobile-form-actions"><Button variant="secondary" className="mobile-secondary" type="button" onClick={testPrint}><Printer size={17} />Test</Button><Button variant="primary" className="mobile-primary" type="submit" disabled={saving}>{saving ? 'Saving…' : 'Save receipt'}</Button></div></form>}
      {page.section === 'payments' && <form className="settings-mobile-form" onSubmit={(event) => saveSettings(event, { payment_methods: methods.map((row) => row.name.trim()).filter(Boolean).join(',') })}><section className="mobile-form-section"><div className="mobile-section-heading"><span>01</span><div><h3>Accepted methods</h3><p>These choices appear during checkout and payments.</p></div></div><div className="settings-repeat-list">{methods.map((row, index) => <div key={index}><span><CreditCard size={18} aria-hidden="true" /></span><Input aria-label={`Payment method ${index + 1}`} value={row.name} onChange={(event) => { const next = methods.map((item) => item.id === row.id ? { ...item, name: event.target.value } : item); setSettings({ ...settings, payment_methods: next.map((item) => item.name).join(',') }); }} /><IconButton variant="ghost" type="button" aria-label={`Remove ${row.name}`} onClick={() => setSettings({ ...settings, payment_methods: methods.filter((item) => item.id !== row.id).map((item) => item.name).join(',') })}><Trash2 size={17} /></IconButton></div>)}</div><Button variant="secondary" className="mobile-secondary" type="button" onClick={() => setSettings({ ...settings, payment_methods: [...methods.map((row) => row.name), 'New method'].join(',') })}><Plus size={17} />Add method</Button></section><div className="mobile-form-actions"><Button variant="secondary" className="mobile-secondary" type="button" onClick={back}>Cancel</Button><Button variant="primary" className="mobile-primary" type="submit" disabled={saving}>Save methods</Button></div></form>}
      {page.section === 'prices' && <><section className="settings-price-page"><p className="settings-page-intro">Create and manage price types. Each type can be set manually or calculated automatically.</p><div className="settings-price-list">{priceRows.map((row) => <article key={row.name}><div className="settings-price-row"><span><strong>{row.name}</strong><small>{row.pricing_mode === 'automatic' ? `${row.markup_percent}% markup · round ${row.rounding}` : 'Manual pricing'}</small><em>{row.productCount} {row.productCount === 1 ? 'product' : 'products'}</em></span><IconButton variant="ghost" className="settings-price-menu" type="button" aria-label={`Actions for ${row.name}`} onClick={() => setActionPrice(row)}><EllipsisVertical size={20} /></IconButton></div></article>)}</div></section><MobileSheet className="mobile-sheet--action-menu" open={Boolean(actionPrice)} title="Price type actions" description={actionPrice?.name || ''} onClose={() => setActionPrice(null)}><div className="mobile-action-menu"><Button variant="plain" type="button" aria-label={`Edit ${actionPrice?.name}`} onClick={() => { const row = actionPrice; setActionPrice(null); onNavigate(`/settings/prices/${encodeURIComponent(row.name)}/edit`); }}><Edit3 size={19} /><span><strong>Edit price type</strong><small>Update its name and pricing rule</small></span><ChevronRight className="mobile-action-chevron" size={18} /></Button><Button variant="danger-ghost" className="danger-action" type="button" aria-label={`Delete ${actionPrice?.name}`} disabled={actionPrice?.productCount > 0 || priceRows.length <= 1} onClick={() => { const row = actionPrice; setActionPrice(null); setDeletePrice(row); }}><Trash2 size={19} /><span><strong>Delete price type</strong><small>{actionPrice?.productCount > 0 ? `Used by ${actionPrice.productCount} products` : priceRows.length <= 1 ? 'At least one price type is required' : 'Remove this unused price type'}</small></span><ChevronRight className="mobile-action-chevron" size={18} /></Button></div></MobileSheet></>}
      {page.section === 'security' && <form className="settings-mobile-form" onSubmit={saveSettings}><SettingsSection title="PIN protection"><div className={`settings-security-state${settings.admin_pin_set === '1' ? '' : ' is-warning'}`}><ShieldAlert size={19} /><span><strong>{settings.admin_pin_set === '1' ? 'Admin PIN is set' : 'Admin PIN is not set'}</strong><small>Protected deletes and stock-affecting changes require this PIN.</small></span></div></SettingsSection><SettingsSection title="Update PIN" description="Enter a new PIN for protected actions."><SettingField label="New admin PIN" hint="Leave blank to keep the current PIN."><SettingsPassword inputMode="numeric" value={settings.admin_pin} onChange={(event) => setSettings({ ...settings, admin_pin: event.target.value })} /></SettingField></SettingsSection><div className="mobile-form-actions"><Button variant="secondary" className="mobile-secondary" type="button" onClick={back}>Cancel</Button><Button variant="primary" className="mobile-primary" type="submit" disabled={saving}>Save security</Button></div></form>}
      {page.section === 'data' && <section className="settings-data-page">
        {trialRestricted && <div className="settings-danger-note" role="status"><ShieldAlert size={19} /><span><strong>{language === 'my' ? 'အခမဲ့စမ်းသုံးကာလ ကန့်သတ်ချက်' : 'Free trial restriction'}</strong><small>{language === 'my' ? 'ဒေတာအရန်ကူးယူခြင်းနှင့် ပြန်လည်ထည့်သွင်းခြင်းအတွက် ငွေပေးချေထားသောအစီအစဉ် လိုအပ်သည်။' : 'Backup download and data restore require a paid plan.'}</small></span></div>}
        <div className="settings-data-grid"><article><CircleCheck size={19} /><small>Database</small><strong>{dataStatus?.ok ? 'Online MySQL' : 'Needs attention'}</strong></article><article><Database size={19} /><small>Business records</small><strong>{Number(dataStatus?.total_records || 0).toLocaleString()}</strong></article><article><Database size={19} /><small>Data version</small><strong>{dataStatus?.schema_version ?? '—'}</strong></article></div>
        <div className="settings-info-note">The backup includes operational business records and shop settings. Accounts, passwords, roles and subscriptions are excluded.</div>
        <SettingsSection title="Back up your data" description="Keep a secure copy of business records and shop settings."><Button variant="primary" className="mobile-primary" type="button" disabled={saving || trialRestricted} onClick={exportBackup}><Download size={17} />{saving ? 'Preparing…' : 'Download backup'}</Button></SettingsSection>
        <SettingsSection title="Restore backup" description="Restore your data from a previously downloaded backup."><Button variant="secondary" className="mobile-secondary" type="button" disabled={trialRestricted} onClick={() => onNavigate('/settings/data/restore')}><Upload size={17} />Restore backup</Button></SettingsSection>
        <div className="settings-data-reset-link"><strong>Start with a fresh business</strong><small>Clear operational records and restore default shop settings.</small><Button variant="danger" className="mobile-danger" type="button" onClick={() => onNavigate('/settings/data/reset')}><Trash2 size={17} />Reset business data</Button></div>
        {trialRestricted && account.role === 'owner' && <Button variant="secondary" className="mobile-secondary" type="button" onClick={() => onNavigate('/billing')}>{language === 'my' ? 'အစီအစဉ်များကြည့်ရန်' : 'View Billing'}</Button>}
      </section>}
      {page.section === 'language' && <form className="settings-mobile-form settings-language-form" onSubmit={saveSettings}><section className="mobile-form-section settings-language-section"><div className="mobile-section-heading"><span>01</span><div><h3>Display language</h3><p>Choose the language used across this device.</p></div></div><SettingsChoices label="Language" className="settings-language-choices" value={settings.language} onChange={language => setSettings({ ...settings, language })} options={[{ value: 'en', label: 'English', description: 'Use English throughout the app' }, { value: 'my', label: 'မြန်မာ', description: 'Use Myanmar throughout the app' }]} /><div className="settings-language-note"><Languages size={17} aria-hidden="true" /><span><strong>{settings.language === 'my' ? 'မြန်မာ' : 'English'}</strong><small>The interface updates after you save this setting.</small></span></div></section><div className="mobile-form-actions"><Button variant="secondary" className="mobile-secondary" type="button" onClick={back}>Cancel</Button><Button variant="primary" className="mobile-primary" type="submit" disabled={saving}>{saving ? 'Saving…' : 'Save language'}</Button></div></form>}
      {page.section === 'about' && <SettingsAbout version={packageInfo.version} contacts={platformContacts} />}</main><MobileDeleteSheet open={Boolean(deletePrice)} title="Delete price type?" description="Only unused price types can be deleted." itemTitle={deletePrice?.name} itemDescription="This unused price type will be removed." confirmLabel="Delete price type" busy={saving} onClose={() => setDeletePrice(null)} onConfirm={deletePriceType} /></>;
}
